Func<Orc.Game.Damage.DamageApplyView, Context, CancellationToken, Task> Handle = async (view, ctx, ct) =>
{
    var host = view.Host;
    if (host is null || !object.ReferenceEquals(view.Target, host)) { return; }

    // 磁反应装甲：具有免疫（伤害归零；不拦索敌、不防抑制）。
    view.IsZeroed = true;
    view.Amount = 0;
};

Func<Orc.Game.Cards.TargetingView, Context, CancellationToken, Task> Handle = async (view, ctx, ct) =>
{
    if (view.Host is not Orc.Game.Cards.UnitCard host) { return; }

    var sourceOwner = view.Source switch
    {
        Orc.Game.Cards.UnitCard unit => unit.Owner,
        Orc.Game.Players.Hq hq => hq.Owner,
        _ => null,
    };
    if (sourceOwner is null || object.ReferenceEquals(sourceOwner, host.Owner)) { return; } // 仅敌方指向

    var x = host.Keywords.GetValue("磁反应装甲");
    if (x is null) { return; }

    var next = x.Value - 1;
    if (next <= 0) { await host.Keywords.RevokeAsync("磁反应装甲"); }
    else { host.Keywords.SetValue("磁反应装甲", next); }
};
